// Author: MiYu. Real JASS save lookup uses the isolated War3 user directory.
#include "session.h"
#include "setup.h"
#include <fstream>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){try{
    if(argc!=4)throw std::runtime_error("Usage: war3_save_exists_tests <data-root> <map> <scratch-root>");auto root=fs::absolute(argv[3])/std::to_wstring(GetCurrentProcessId());if(fs::exists(root))throw std::runtime_error("Scratch directory already exists");if(!SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",root.c_str()))throw std::runtime_error("Cannot set isolated user directory");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;auto sources=jass::Program::read(archives).sources();sources.push_back({"save-fixture.j","function TestSeedZone takes string name returns nothing\nset udg_ZoneSaves[1]=name\nendfunction\nfunction TestSeedFolders takes string prefix, string zone returns nothing\nset udg_BlizzardFolder=prefix\nset udg_ZoneFolder=zone\nset udg_ZoneCount=1\nendfunction\n","authored save event fixture"});auto restoredSources=sources;ScriptSession session(jass::Module::compile(jass::Program::parse(std::move(sources))),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto exists=[&](std::string name){return vm.invoke("SaveGameExists",std::array{vm.string(name)}).bits!=0;};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};require(!vm.invoke("GetSaveBasicFilename").text && vm.global("gg_trg_User_Save").bits,"Original save event trigger unavailable");auto prefix=vm.global("udg_BlizzardFolder");require(prefix.text && *prefix.text=="Blizzard\\", "Original zone folder was not initialized");session.notifyGameSaved("Blizzard\\Slot.one.w3z");auto folder=vm.global("udg_SaveFolder");require(folder.text && *folder.text==(prefix.text?*prefix.text:std::string{})+"Slot.one","Original save action did not consume the save filename");require(!vm.invoke("GetSaveBasicFilename").text,"Save event filename leaked into host context");require(!exists("Blizzard\\Zones\\OrcX01.w3z"),"Missing save reported present");auto dir=root/L"Saves"/L"Blizzard"/L"Zones";fs::create_directories(dir);std::ofstream file(dir/L"OrcX01.w3z",std::ios::binary);file<<"test-save";file.close();require(bool(file),"Could not create isolated save");vm.invoke("TestSeedZone",std::array{vm.string("OrcX01.w3z")});session.notifyGameSaved("Blizzard\\Slot.one.w3z");auto eventCopy=root/L"Saves"/L"Blizzard"/L"Slot.one"/L"OrcX01.w3z";std::ifstream eventFile(eventCopy,std::ios::binary);require(bool(eventFile) && std::string(std::istreambuf_iterator<char>(eventFile),{})=="test-save","Original save action did not back up the zone");auto identity=[](std::string_view,std::uint32_t id){return id;};auto savedTriggers=session.encodeTriggers(identity),savedEvents=session.encodeGameEvents(identity);ScriptSession restored(jass::Module::compile(jass::Program::parse(std::move(restoredSources))),info);restored.attachWorld(World::read(archives));restored.audioMuted(true);restored.audioSimulationClock();restored.configure();PlayerSetup restoredSetup(info,restored.config());restored.applySetup(restoredSetup);auto triggerMap=restored.restoreTriggers(savedTriggers);auto decodeTrigger=[&](std::string_view type,std::uint32_t id){auto it=triggerMap.find({std::string(type),id});return it==triggerMap.end()?0u:it->second;};auto corrupt=savedEvents;corrupt.back()^=1;bool rejected=false;try{restored.rebuildGameEvents(corrupt,decodeTrigger);}catch(const std::exception&){rejected=true;}require(rejected && restored.liveObjects(NativeKind::Event)==0,"Corrupt game event snapshot created events");auto eventMap=restored.rebuildGameEvents(savedEvents,decodeTrigger);require(!eventMap.empty(),"Original game event snapshot was empty");auto encodeRestored=[&](std::string_view type,std::uint32_t id){if(type=="event"){for(auto [stable,local]:eventMap)if(local==id)return stable;}else for(auto& [key,local]:triggerMap)if(key.first==type && local==id)return key.second;return 0u;};require(restored.encodeGameEvents(encodeRestored)==savedEvents,"Original game event reconstruction differed");auto& restoredVm=restored.runtime();auto zoneFolder=vm.global("udg_ZoneFolder");require(bool(zoneFolder.text),"Original zone folder missing");restoredVm.invoke("TestSeedFolders",std::array{restoredVm.string(*prefix.text),restoredVm.string(*zoneFolder.text)});restoredVm.invoke("TestSeedZone",std::array{restoredVm.string("OrcX01.w3z")});restored.notifyGameSaved("Blizzard\\Slot.two.w3z");auto restoredCopy=root/L"Saves"/L"Blizzard"/L"Slot.two"/L"OrcX01.w3z";std::ifstream restoredFile(restoredCopy,std::ios::binary);require(bool(restoredFile) && std::string(std::istreambuf_iterator<char>(restoredFile),{})=="test-save","Restored original User Save did not back up the zone");auto userSave=triggerMap.at({"trigger",vm.global("gg_trg_User_Save").bits});auto countBefore=restored.liveObjects(NativeKind::Event);restoredVm.invoke("DestroyTrigger",std::array{restoredVm.handle("trigger",userSave)});require(restored.liveObjects(NativeKind::Event)+1==countBefore,"Rebuilt save event did not follow trigger lifetime");vm.invoke("TestSeedZone",std::array{vm.string("")});require(exists("Blizzard\\Zones\\OrcX01.w3z"),"Existing save not found");require(exists("blizzard/zones/orcx01.w3z"),"Windows case or separator lookup differs");require(!exists("Blizzard\\Zones") && !exists("..\\OrcX01.w3z") && !exists("C:\\OrcX01.w3z"),"Invalid save name was accepted");auto copy=[&](std::string from,std::string to){return vm.invoke("CopySaveGameBJ",std::array{vm.string(from),vm.string(to)}).bits!=0;};auto saved=std::string("Blizzard\\Zones\\OrcX01.w3z"),backup=std::string("Blizzard\\Slot1\\OrcX01.w3z");require(copy(saved,backup) && exists(backup),"Save copy did not create destination");auto read=[&](const fs::path& path){std::ifstream input(path,std::ios::binary);return std::string(std::istreambuf_iterator<char>(input),{});};auto backupFile=root/L"Saves"/L"Blizzard"/L"Slot1"/L"OrcX01.w3z";require(read(backupFile)=="test-save","Copied save bytes differ");{std::ofstream replace(backupFile,std::ios::binary|std::ios::trunc);replace<<"old";}require(copy(saved,backup) && read(backupFile)=="test-save","Save overwrite did not replace contents");require(!copy("Blizzard\\Zones\\missing.w3z",backup) && read(backupFile)=="test-save","Missing source changed destination");require(!copy(saved,"..\\escape.w3z") && !copy(saved,saved) && !exists("Blizzard\\Zones\\NUL.w3z") && !exists(".. \\OrcX01.w3z"),"Unsafe save copy path accepted");auto rename=[&](std::string from,std::string to){return vm.invoke("RenameSaveDirectoryBJ",std::array{vm.string(from),vm.string(to)}).bits!=0;};auto source=root/L"Saves"/L"Blizzard"/L"RenameSource";fs::create_directories(source/L"nested");{std::ofstream nestedFile(source/L"nested"/L"state.w3z",std::ios::binary);nestedFile<<"rename-data";}require(rename("Blizzard\\RenameSource","Blizzard\\Archive\\Moved"),"Save directory rename failed");auto moved=root/L"Saves"/L"Blizzard"/L"Archive"/L"Moved";require(!fs::exists(source) && read(moved/L"nested"/L"state.w3z")=="rename-data" && exists(backup),"Save directory rename lost data or changed a sibling");fs::create_directories(source);{std::ofstream marker(source/L"keep.w3z",std::ios::binary);marker<<"keep";}require(!rename("Blizzard\\RenameSource","Blizzard\\Archive\\Moved") && !rename("Blizzard\\Missing","Blizzard\\Unused") && !rename("Blizzard\\RenameSource","Blizzard\\RenameSource\\Child") && !rename("Blizzard\\RenameSource","..\\escape") && read(source/L"keep.w3z")=="keep" && read(moved/L"nested"/L"state.w3z")=="rename-data","Invalid rename changed source or destination");auto remove=[&](std::string name){return vm.invoke("RemoveSaveDirectoryBJ",std::array{vm.string(name)}).bits!=0;};require(!remove("") && !remove("..\\..") && !remove("Blizzard\\missing") && exists(backup),"Unsafe or missing save directory removed");auto nested=dir/L"nested";fs::create_directories(nested);{std::ofstream nestedFile(nested/L"zone.w3z",std::ios::binary);nestedFile<<"zone";}auto outside=root/L"outside";fs::create_directories(outside);{std::ofstream marker(outside/L"keep.txt",std::ios::binary);marker<<"keep";}auto link=dir/L"link";if(CreateSymbolicLinkW(link.c_str(),outside.c_str(),SYMBOLIC_LINK_FLAG_DIRECTORY|0x2)){require(!remove("Blizzard\\Zones") && exists(saved) && fs::exists(outside/L"keep.txt"),"Save removal followed a directory link");require(RemoveDirectoryW(link.c_str())!=0,"Could not remove isolated link");std::cout<<"PASS directory link rejection\n";}else std::cout<<"SKIP directory link creation\n";require(remove("Blizzard\\Zones") && !fs::exists(dir) && exists(backup) && fs::exists(outside/L"keep.txt"),"Save directory removal affected wrong files");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS save lookup, copy, directory rename and removal\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
}catch(const std::exception& e){std::cerr<<"error="<<e.what()<<'\n';return 1;}}
